13	// bubbletea v2 removes KeyMsg.Runes, .Alt, .Paste and the tea.KeyType constants.
14	// Production code reads the key by its name (String()) only, so the migration
15	// does not have to rewrite it (DEVDESK-200). internal/ui/testutil is the one place
16	// that builds keys and is out of scope.
17	//
18	// DEVDESK-201: the v2 key types KeyPressMsg, KeyReleaseMsg and
19	// KeyboardEnhancementsMsg start with "Key" but are not legacy; they are allowed
20	// here. tea.KeyMsg (now an interface that also matches releases) is refused by
21	// TestNoProductionCodeMatchesTheKeyMsgInterface instead.
22	
23	// v2KeyTypes are the Key-prefixed names that exist in bubbletea v2 and are not
24	// legacy. "Key" is the struct, KeyMsg the interface.
25	var v2KeyTypes = map[string]bool{
26		"KeyMsg": true, "Key": true, "KeyPressMsg": true, "KeyReleaseMsg": true, "KeyboardEnhancementsMsg": true,
27	}
28	
29	// legacyKeyReads returns "path:line" for every use, in a production file, of a
30	// v1-only key field or key type constant: X.Runes, X.Alt, X.Paste, and tea.Key<Name>
31	// other than tea.KeyMsg and tea.Key. tea.KeyType is flagged: it disappears in v2.
32	// teaName is the local name of the bubbletea import; a file without it is skipped.
33	func legacyKeyReads(fset *token.FileSet, path string, file *ast.File, teaName string) []string {
34		if teaName == "" {
35			return nil
36		}
37		var out []string
38		ast.Inspect(file, func(n ast.Node) bool {
39			sel, ok := n.(*ast.SelectorExpr)
40			if !ok {
41				return true
42			}
43			name := sel.Sel.Name
44			legacy := name == "Runes" || name == "Alt" || name == "Paste"
45			if id, ok := sel.X.(*ast.Ident); ok && id.Name == teaName &&
46				strings.HasPrefix(name, "Key") && !v2KeyTypes[name] {
47				legacy = true
48			}
49			if legacy {
50				out = append(out, filepath.ToSlash(path)+":"+strconv.Itoa(fset.Position(sel.Sel.Pos()).Line))
51			}
52			return true
53		})
54		return out
55	}
