57	// teaImportName returns the local name of the bubbletea import, "" if absent.
58	func teaImportName(file *ast.File) string {
59		for _, imp := range file.Imports {
60			p, err := strconv.Unquote(imp.Path.Value)
61			if err != nil || p != bubbleteaPath {
62				continue
63			}
64			if imp.Name != nil {
65				return imp.Name.Name
66			}
67			return "tea"
68		}
69		return ""
70	}
